-- Consent documents (152-ФЗ). New wording = new version row; never edit a published version.

INSERT INTO consent_documents (id, kind, version, title, body, required_for) VALUES
('0191f000-0000-7000-8000-000000000001', 'pd_processing', 1,
 'Согласие на обработку персональных данных',
 $$Я даю согласие оператору платформы на обработку моих персональных данных (ФИО, контактные данные, сведения об образовании, опыте работы, навыках, результатах тестирования и спортивных достижениях) в целях подбора работы и взаимодействия с работодателями в соответствии с Федеральным законом от 27.07.2006 № 152-ФЗ «О персональных данных». Обработка включает сбор, запись, систематизацию, хранение, уточнение, использование, обезличивание и удаление. Контактные данные передаются работодателю только после того, как я приму его приглашение или сам откликнусь на вакансию. Согласие действует до его отзыва; отозвать его можно в настройках профиля.$$,
 '{candidate,employer}'),
('0191f000-0000-7000-8000-000000000002', 'pd_publication', 1,
 'Согласие на публикацию профиля для работодателей',
 $$Я согласен(на), что обезличенная карточка моего профиля (категория, результаты тестирования, подтверждённые навыки, достижения ФСП, опыт без названий компаний — по моим настройкам приватности, ожидания по зарплате) будет доступна зарегистрированным работодателям платформы. Имя и контакты не публикуются без моего отдельного действия. Отзыв согласия скрывает профиль из поиска.$$,
 '{candidate}'),
('0191f000-0000-7000-8000-000000000003', 'terms', 1,
 'Пользовательское соглашение',
 $$Платформа связывает работодателей и соискателей напрямую. Работодатель обязуется указывать реальный уровень заработной платы в приглашениях и вакансиях и не использовать контактные данные кандидатов в целях, не связанных с подбором. Количество приглашений ограничено квотой. Жалобы на недобросовестное поведение рассматриваются администрацией.$$,
 '{candidate,employer}');
